export type AppEventDto =
  | {
      readonly topic: "solve://progress";
      readonly payload: {
        readonly type: "solveProgress";
        readonly payload: {
          readonly context: EventContextDto;
          readonly phase: SolvePhase;
          readonly percent: number | null;
        };
      };
    }
  | {
      readonly topic: "solve://completed";
      readonly payload: {
        readonly type: "solveCompleted";
        readonly payload: {
          readonly context: EventContextDto;
          readonly status: SolveStatus;
          readonly solutionId: UuidV7 | null;
        };
      };
    }
  | {
      readonly topic: "counterfactual://progress";
      readonly payload: {
        readonly type: "counterfactualProgress";
        readonly payload: {
          readonly context: EventContextDto;
          readonly jobId: UuidV7;
          readonly phase: CounterfactualProgressPhase;
        };
      };
    }
  | {
      readonly topic: "scenario://changed";
      readonly payload: {
        readonly type: "scenarioChanged";
        readonly payload: { readonly context: EventContextDto; readonly changeSet: ChangeSet };
      };
    }
  | {
      readonly topic: "scenario://validation-changed";
      readonly payload: {
        readonly type: "scenarioValidationChanged";
        readonly payload: {
          readonly context: EventContextDto;
          readonly validationDelta: ValidationDelta;
        };
      };
    }
  | {
      readonly topic: "app://notification";
      readonly payload: {
        readonly type: "appNotification";
        readonly payload: {
          readonly context: EventContextDto;
          readonly code: string;
          readonly message: string;
        };
      };
    };

export type SolveProgressEvent = Extract<
  AppEventDto,
  { readonly topic: "solve://progress" }
>["payload"];
export type SolveCompletedEvent = Extract<
  AppEventDto,
  { readonly topic: "solve://completed" }
>["payload"];
export type ScenarioChangedEvent = Extract<
  AppEventDto,
  { readonly topic: "scenario://changed" }
>["payload"];
export type ScenarioValidationChangedEvent = Extract<
  AppEventDto,
  { readonly topic: "scenario://validation-changed" }
>["payload"];
export type CounterfactualProgressEvent = Extract<
  AppEventDto,
  { readonly topic: "counterfactual://progress" }
>["payload"];
export type AppNotificationEvent = Extract<
  AppEventDto,
  { readonly topic: "app://notification" }
>["payload"];
export interface LibraryRefreshRequiredEvent {
  readonly reason: "event-subscription-lagged";
}

export function onSolveProgress(
  listener: (event: SolveProgressEvent) => void,
): Promise<UnlistenFn> {
  return listenParsed("solve://progress", isSolveProgress, listener);
}

export function onSolveCompleted(
  listener: (event: SolveCompletedEvent) => void,
): Promise<UnlistenFn> {
  return listenParsed("solve://completed", isSolveCompleted, listener);
}

export function onScenarioChanged(
  listener: (event: ScenarioChangedEvent) => void,
): Promise<UnlistenFn> {
  return listenParsed("scenario://changed", isScenarioChanged, listener);
}

export function onScenarioValidationChanged(
  listener: (event: ScenarioValidationChangedEvent) => void,
): Promise<UnlistenFn> {
  return listenParsed("scenario://validation-changed", isScenarioValidationChanged, listener);
}

export function onCounterfactualProgress(
  listener: (event: CounterfactualProgressEvent) => void,
): Promise<UnlistenFn> {
  return listenParsed("counterfactual://progress", isCounterfactualProgress, listener);
}

export function onAppNotification(
  listener: (event: AppNotificationEvent) => void,
): Promise<UnlistenFn> {
  return listenParsed("app://notification", isAppNotification, listener);
}
export function onLibraryRefreshRequired(
  listener: (event: LibraryRefreshRequiredEvent) => void,
): Promise<UnlistenFn> {
  return listenParsed("library://refresh-required", isLibraryRefresh, listener);
}

function listenParsed<T>(
  topic: string,
  guard: Guard<T>,
  listener: (event: T) => void,
): Promise<UnlistenFn> {
  return listen<unknown>(topic, ({ payload }) => {
    try {
      if (boundedJson(payload, RESPONSE_MAX_BYTES) && guard(payload)) listener(payload);
    } catch {
      // Event delivery is advisory. Invalid payloads or a failed consumer cannot change invoke outcomes.
    }
  });
}

