function newRequestId(): UuidV7 {
  const bytes = window.crypto.getRandomValues(new Uint8Array(16));
  const timestamp = BigInt(Date.now());
  bytes[0] = Number((timestamp >> 40n) & 0xffn);
  bytes[1] = Number((timestamp >> 32n) & 0xffn);
  bytes[2] = Number((timestamp >> 24n) & 0xffn);
  bytes[3] = Number((timestamp >> 16n) & 0xffn);
  bytes[4] = Number((timestamp >> 8n) & 0xffn);
  bytes[5] = Number(timestamp & 0xffn);
  const versionByte = bytes[6];
  const variantByte = bytes[8];
  if (versionByte === undefined || variantByte === undefined) {
    throw new Error("Unable to construct request ID");
  }
  bytes[6] = (versionByte & 0x0f) | 0x70;
  bytes[8] = (variantByte & 0x3f) | 0x80;
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

const INT64_MIN = -(1n << 63n);
const INT64_MAX = (1n << 63n) - 1n;
const CANONICAL_DECIMAL_INTEGER = /^(?:0|-?[1-9][0-9]*)$/;

function assertInt64(value: unknown, field: string): asserts value is Int64 {
  if (typeof value !== "string" || !CANONICAL_DECIMAL_INTEGER.test(value)) {
    throw new RangeError(`${field} must be a canonical signed 64-bit decimal string`);
  }
  const parsed = BigInt(value);
  if (parsed < INT64_MIN || parsed > INT64_MAX) {
    throw new RangeError(`${field} is outside the signed 64-bit range`);
  }
}

function assertAssignmentValue(value: AssignmentValue): void {
  if (value.type === "integer") {
    assertInt64(value.value, "Assignment integer");
  } else if (value.type === "interval") {
    assertInt64(value.value.start, "Assignment interval start");
    assertInt64(value.value.duration, "Assignment interval duration");
    assertInt64(value.value.end, "Assignment interval end");
  }
}

// Matches the complete command receipt ceiling, including lossless integer quoting and framing.
const COMMAND_RESULT_COMPACT_MAX_BYTES = 144 * 1_048_576 + 65_536;
const RESPONSE_MAX_BYTES = (COMMAND_RESULT_COMPACT_MAX_BYTES * 9) / 8 + 65_536;
async function call<T>(
  command: CatalogCommand,
  request: object,
  guard: Guard<T>,
  options: {
    readonly maximumBytes?: number;
    readonly onProgress?: Channel;
    readonly revisionKey?: ResponseRevisionKey<T>;
  } = {},
): Promise<ApiResponseDto<T>> {
  const revision = "expectedRevision" in request ? request.expectedRevision : undefined;
  if (revision !== undefined && revision !== null && !isRevision(revision)) {
    throw new RangeError("Revision must be a non-negative JavaScript safe integer");
  }
  const budget = "totalBudgetMilliseconds" in request ? request.totalBudgetMilliseconds : undefined;
  if (
    budget !== undefined &&
    (!isU32(budget) || budget <= 0 || budget > COUNTERFACTUAL_TOTAL_BUDGET_MAX_MILLISECONDS_V1)
  ) {
    throw new RangeError(
      "Counterfactual budget must be an integer between 1 and 30000 milliseconds",
    );
  }
  const requestId =
    "requestId" in request
      ? request.requestId
      : "cancelRequestId" in request
        ? request.cancelRequestId
        : undefined;
  if (!isUuid(requestId)) throw new RangeError("A canonical UUIDv7 request identity is required");
  let value: unknown;
  try {
    value = await invoke<unknown>(
      command,
      options.onProgress === undefined ? { request } : { request, onProgress: options.onProgress },
    );
  } catch (error: unknown) {
    if (boundedJson(error, 16 * 1_048_576) && isApiError(error)) throw error;
    throw invalidResponse();
  }
  const response = parseResponse(
    value,
    requestId,
    guard,
    options.maximumBytes ?? RESPONSE_MAX_BYTES,
    options.revisionKey,
  );
  if (
    "scenarioId" in request &&
    isObject(response.result) &&
    Object.hasOwn(response.result, "scenarioId") &&
    response.result.scenarioId !== request.scenarioId
  )
    throw invalidResponse();
  return response;
}

export interface SetupOperation<T> {
  readonly requestId: UuidV7;
  readonly result: Promise<ApiResponseDto<T>>;
  /** Cancellation acknowledgement is not a terminal outcome. Continue awaiting result. */
  cancel(): Promise<ApiResponseDto<OperationCancelledV1>>;
  release(): Promise<ApiResponseDto<OperationReleasedV1>>;
  /** A disposed presentation context must not receive this operation's data. */
  isCurrent(): boolean;
}
type SetupOperationCommand =
  | "scenario_get_summary"
  | "scenario_get_setup_status"
  | "scenario_get_view"
  | "scenario_get_entity"
  | "scenario_search_entities"
  | "scenario_get_rule_catalog"
  | "scenario_validate"
  | "workforce_apply_reviewed_generation";
interface NativeCallbackRegistry {
  readonly unregisterCallback: (id: number) => void;
}
function hasCallbackRegistry(value: unknown): value is NativeCallbackRegistry {
  return isObject(value) && typeof value.unregisterCallback === "function";
}
function inactiveOperation(): Error & ApiErrorDto {
  const error: ApiErrorDto = {
    code: "operation.context_disposed",
    category: "protocol",
    message: "This workspace context was closed before the operation started.",
    retryable: false,
    fieldErrors: [],
    details: null,
    diagnosticId: null,
  };
  return Object.assign(new Error(error.message), error);
}

/** One immutable scenario/revision presentation context; dispose it when that context changes. */
export class SetupOperationScope {
  readonly #context: OperationContextV1;
  readonly #windowLabel: string;
  readonly #callbacks: NativeCallbackRegistry;
  readonly #running = new Set<{ readonly dispose: () => void }>();
  #disposed = false;

  constructor(scenarioId: UuidV7, expectedRevision: Revision | null) {
    if (!isUuid(scenarioId) || (expectedRevision !== null && !isRevision(expectedRevision))) {
      throw new RangeError("A canonical scenario identity and exact safe revision are required");
    }
    const callbacks: unknown = Reflect.get(window, "__TAURI_INTERNALS__");
    if (!hasCallbackRegistry(callbacks))
      throw new Error("The native operation channel is unavailable");
    this.#callbacks = callbacks;
    this.#windowLabel = getCurrentWebviewWindow().label;
    this.#context = Object.freeze({ kind: "scenario", scenarioId, expectedRevision });
  }

  get context(): OperationContextV1 {
    return this.#context;
  }

  dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    for (const operation of this.#running) operation.dispose();
  }

  run<T>(
    command: SetupOperationCommand,
    purpose: OperationPurposeV1,
    payload: object,
    guard: Guard<T>,
    maximumBytes: number,
    revisionKey: ResponseRevisionKey<T>,
    onProgress?: (event: OperationProgressV1) => void,
  ): SetupOperation<T> {
    if (this.#disposed) throw inactiveOperation();
    if (!boundedJson(payload, RESPONSE_MAX_BYTES))
      throw new RangeError("The operation request exceeds its JSON limits");
    // Capture before the prepare await: later edits to a Vue draft cannot rebind this request.
    const snapshot: unknown = JSON.parse(JSON.stringify(payload));
    if (!isObject(snapshot)) throw new RangeError("The operation request must be a JSON object");
    const requestId = newRequestId();
    const context = this.context;
    const prepared = call(
      "operation_prepare",
      {
        requestId: newRequestId(),
        schemaVersion: 1,
        purpose,
        context,
      },
      isOperationPrepared,
    );
    const state = { cancellationRequested: false, releaseRequested: false };
    const isCurrent = (): boolean => !this.#disposed && !state.releaseRequested;
    let cancelAcknowledgement: Promise<ApiResponseDto<OperationCancelledV1>> | undefined;
    let releaseAcknowledgement: Promise<ApiResponseDto<OperationReleasedV1>> | undefined;
    let detachChannel: (() => void) | undefined;
    const detach = (): void => {
      const cleanup = detachChannel;
      detachChannel = undefined;
      try {
        cleanup?.();
      } catch {
        /* Cleanup cannot replace a committed terminal result. */
      }
    };
    const cancel = (): Promise<ApiResponseDto<OperationCancelledV1>> => {
      state.cancellationRequested = true;
      cancelAcknowledgement ??= prepared.then(({ result }) =>
        call(
          "operation_cancel",
          {
            requestId: newRequestId(),
            schemaVersion: 1,
            operationId: result.operationId,
          },
          isOperationCancelled,
        ),
      );
      return cancelAcknowledgement;
    };
    const releaseNative = (): Promise<ApiResponseDto<OperationReleasedV1>> => {
      releaseAcknowledgement ??= prepared.then(({ result }) =>
        call(
          "operation_release",
          {
            requestId: newRequestId(),
            schemaVersion: 1,
            operationId: result.operationId,
          },
          isOperationReleased,
        ),
      );
      return releaseAcknowledgement;
    };
    const release = (): Promise<ApiResponseDto<OperationReleasedV1>> => {
      state.releaseRequested = true;
      detach();
      return releaseNative();
    };
    const owned = {
      dispose: (): void => {
        void release().catch(() => undefined);
      },
    };
    this.#running.add(owned);
    const result = (async (): Promise<ApiResponseDto<T>> => {
      let receivedSuccess = false;
      try {
        const reservation = await prepared;
        if (!isCurrent()) {
          await release();
          throw inactiveOperation();
        }
        if (state.cancellationRequested) await cancel();
        if (!isCurrent()) {
          await release();
          throw inactiveOperation();
        }
        const operationId = reservation.result.operationId;
        let sequence = 0;
        const channel = new Channel<unknown>((value) => {
          try {
            if (
              !isCurrent() ||
              onProgress === undefined ||
              !boundedJson(value, 4096) ||
              !isOperationProgress(value) ||
              value.operationId !== operationId ||
              value.requestId !== requestId ||
              value.windowLabel !== this.#windowLabel ||
              value.context.scenarioId !== context.scenarioId ||
              value.context.expectedRevision !== context.expectedRevision ||
              value.sequence <= sequence
            )
              return;
            sequence = value.sequence;
            onProgress(value);
          } catch {
            // A parser or consumer exception must not stall the SDK's channel ordering/cleanup.
          }
        });
        // Pinned @tauri-apps/api2.11.1 has no public Channel disposal. Its callback deletion is
        // idempotent and also covers ACL/dispatch failures where Rust never constructs a Channel.
        detachChannel = () => {
          this.#callbacks.unregisterCallback(channel.id);
        };
        const response = await call(
          command,
          {
            ...snapshot,
            requestId,
            operationId,
            scenarioId: context.scenarioId,
            expectedRevision: context.expectedRevision,
          },
          guard,
          { maximumBytes, onProgress: channel, revisionKey },
        );
        receivedSuccess = true;
        return response;
      } finally {
        detach();
        this.#running.delete(owned);
        // A failed/undelivered invoke may not have claimed the reservation. Never replay it.
        if (!receivedSuccess) void releaseNative().catch(() => undefined);
      }
    })();
    return { requestId, result, cancel, release, isCurrent };
  }
}

